/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_CLAIM_PROCESS_STEP_LOG
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_CLAIM   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : (not declared in data_7.js)
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 9 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_CLAIM_HK
   hashdiff    : SAT_CLAIM_PROCESS_STEP_LOG_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   INTRA-RUN FAN-IN, 1 attribute/run pair(s) with more than one writer, of
   which 0 are genuinely ARBITRARY. WITHIN one run several source views
   write the same attribute and the map declares NO precedence among them,
   so max() picks arbitrarily -- BUT ONLY AMONG UNDISCRIMINATED WRITERS. A
   writer carrying a resolved `instance` or a declared `redundant_of` is
   SEPARATED, not competing: a nominee's name and a policyholder's name on
   one satellite are DIFFERENT ROWS. BOTH SCOPES are quoted below because a
   bare writer count overstates the arbitrariness -- on PARTY_FULL_NAME it
   overstates it nearly fivefold.
   DECLARED, NOT RESOLVED: choosing among same-run writers would invent an
   authority the map does not provide. NO CROSS-RUN DECISION REACHES THIS.
     STEP_START_TIMESTAMP                   opus_health_v2         2 writer(s), of which 1 UNDISCRIMINATED (0 separated by a resolved instance, 1 by redundant_of)
*/

with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , LOG_ID as PROCESS_LOG_REFERENCE
        , LOG_TYPE as LOG_TYPE_CODE
        , PROCESS_TYPE as PROCESS_TYPE_CODE
        , UPDATED_ON as STEP_START_TIMESTAMP
        , END_ON as STEP_END_TIMESTAMP
        , UPDATED_BY as STEP_ACTOR_USER_REFERENCE
        , STATUS_TYPE as STEP_STATUS_CODE
        , NEXT_CASE as NEXT_CASE_REFERENCE
        , ACTUAL_START_ON as STEP_ACTUAL_START_TIMESTAMP
        , 'BJAZ_HM_USER_TAT' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_user_tat') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then PROCESS_LOG_REFERENCE end) as PROCESS_LOG_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then LOG_TYPE_CODE end) as LOG_TYPE_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then PROCESS_TYPE_CODE end) as PROCESS_TYPE_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then STEP_START_TIMESTAMP end) as STEP_START_TIMESTAMP,
        max(case when SOURCE_RUN = 'opus_health_v2' then STEP_END_TIMESTAMP end) as STEP_END_TIMESTAMP,
        max(case when SOURCE_RUN = 'opus_health_v2' then STEP_ACTOR_USER_REFERENCE end) as STEP_ACTOR_USER_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then STEP_STATUS_CODE end) as STEP_STATUS_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then NEXT_CASE_REFERENCE end) as NEXT_CASE_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then STEP_ACTUAL_START_TIMESTAMP end) as STEP_ACTUAL_START_TIMESTAMP,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when PROCESS_LOG_REFERENCE is not null or LOG_TYPE_CODE is not null or PROCESS_TYPE_CODE is not null or STEP_START_TIMESTAMP is not null or STEP_END_TIMESTAMP is not null or STEP_ACTOR_USER_REFERENCE is not null or STEP_STATUS_CODE is not null or NEXT_CASE_REFERENCE is not null or STEP_ACTUAL_START_TIMESTAMP is not null
                     then md5(upper(coalesce(cast(PROCESS_LOG_REFERENCE as varchar), '') || '|' || coalesce(cast(LOG_TYPE_CODE as varchar), '') || '|' || coalesce(cast(PROCESS_TYPE_CODE as varchar), '') || '|' || coalesce(cast(STEP_START_TIMESTAMP as varchar), '') || '|' || coalesce(cast(STEP_END_TIMESTAMP as varchar), '') || '|' || coalesce(cast(STEP_ACTOR_USER_REFERENCE as varchar), '') || '|' || coalesce(cast(STEP_STATUS_CODE as varchar), '') || '|' || coalesce(cast(NEXT_CASE_REFERENCE as varchar), '') || '|' || coalesce(cast(STEP_ACTUAL_START_TIMESTAMP as varchar), '')))
                end as SAT_CLAIM_PROCESS_STEP_LOG_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_PROCESS_STEP_LOG_HASHDIFF is not null
